// Chart.js 4.5.1 (MIT). Bundle the UMD runtime for offline Web/iOS/Android charts.
const fs=require('fs'),path=require('path');
const file=process.argv[2]||path.join(path.dirname(require.resolve('chart.js')),'chart.umd.js');
const js=fs.readFileSync(file,'utf8').replace(/\/\/# sourceMappingURL=.*$/gm,'');
const out=path.join(__dirname,'../src/features/company/dashboard/chartJsBundle.ts');
fs.writeFileSync(out,'// Generated by scripts/build-dashboard-chart.cjs. Chart.js 4.5.1, MIT.\nexport const CHART_JS_SOURCE = '+JSON.stringify(js)+';\n');
console.log('Bundled Chart.js runtime.');
